code_example:
vector<int> v1(10);
// Initializes v1 with 10 elements.
// Built-in types (like int) are zero-initialized: {0, 0, ..., 0}

vector<double> v2(5, 3.14);
// Initializes v2 with 5 elements, all set to 3.14:
// {3.14, 3.14, 3.14, 3.14, 3.14}

// Use .size() and .capacity()
size_t initial_size = v1.size();   // 10
size_t initial_cap = v1.capacity(); // >= 10
